namespace ControlDeDinero.Domain;

public class Payment
{
    private Payment() { } // EF Core

    internal Payment(Guid loanId, DateTime paymentDate, decimal amount, string? notes)
    {
        // Id is generated by EF when saving (see AuditEvent).
        LoanId = loanId;
        PaymentDate = paymentDate;
        Amount = amount;
        Notes = notes;
    }

    public Guid Id { get; private set; }
    public Guid LoanId { get; private set; }

    public DateTime PaymentDate { get; private set; }
    public decimal Amount { get; private set; }
    public string? Notes { get; private set; }

    // A voided payment is never deleted: it stays in the history, flagged, and stops counting.
    public bool IsVoided { get; private set; }
    public DateTime? VoidedAtUtc { get; private set; }
    public string? VoidReason { get; private set; }

    public Loan? Loan { get; private set; }
    public ICollection<PaymentAllocation> Allocations { get; private set; } = new List<PaymentAllocation>();

    internal void Void(DateTime voidedAtUtc, string? reason)
    {
        IsVoided = true;
        VoidedAtUtc = voidedAtUtc;
        VoidReason = reason;
    }

    internal void Allocate(decimal principalPaid, decimal interestPaid)
    {
        Allocations.Add(new PaymentAllocation(LoanId, principalPaid, interestPaid));
    }
}
